<?php
$mpm='/etc/apache2/mods-enabled/mpm_event.conf';
$bak=$mpm.'.bak.thumb.'.date('YmdHis');
if (!is_file($mpm)) { echo "no mpm_event\n"; exit(1); }
copy($mpm,$bak);
echo "backed $bak\n";
$cfg=<<<'CFG'
# Generated by bahmantoggle apache-accept-fix (sales thumbs / accept queue)
ServerLimit              16
StartServers             4
MinSpareThreads          50
MaxSpareThreads          150
ThreadsPerChild          25
MaxRequestWorkers        400
MaxConnectionsPerChild   0
ListenBacklog            4096
CFG;
file_put_contents($mpm,$cfg);
echo "wrote mpm_event.conf\n";
echo file_get_contents($mpm);

# Also try raise kernel backlog via plesk/sudo if available
echo "sysctl:\n".trim(shell_exec('sysctl -w net.core.somaxconn=8192 net.ipv4.tcp_max_syn_backlog=16384 2>&1'))."\n";
echo "sudo_sysctl:\n".trim(shell_exec('sudo -n sysctl -w net.core.somaxconn=8192 net.ipv4.tcp_max_syn_backlog=16384 2>&1'))."\n";

# graceful restart apache
echo "restart:\n".trim(shell_exec('apache2ctl configtest 2>&1'))."\n";
echo trim(shell_exec('systemctl reload apache2 2>&1 || service apache2 reload 2>&1 || apache2ctl graceful 2>&1'))."\n";
sleep(2);
echo "listen_after=\n".trim(shell_exec("ss -lnt '( sport = :80 or sport = :443 )' 2>/dev/null"))."\n";
echo "httpd_threads=".trim(shell_exec("ps -eo cmd | grep -E '[a]pache2|[h]ttpd' | wc -l"))."\n";
echo "syn_recv=".trim(shell_exec("ss -ant state syn-recv 2>/dev/null | wc -l"))."\n";

# verify static thumbs local burst
$urls=[
'https://172.20.14.76/thumb/61bb1145-d84f-11f1-b563-005056b972d8/600',
'https://172.20.14.76/thumb/340d73a9-d74b-11f1-b563-005056b972d8/600',
'https://172.20.14.76/thumb/2ec8e505-d74c-11f1-b563-005056b972d8/600',
];
for ($i=0;$i<20;$i++) {
  foreach ($urls as $u) {
    shell_exec('curl -sk --max-time 3 -o /dev/null -H "Host: sitefile.bahman.ir" '.escapeshellarg($u).' >/dev/null 2>&1 &');
  }
}
sleep(2);
echo "burst_done syn=".trim(shell_exec("ss -ant state syn-recv 2>/dev/null | wc -l"))." listen80=\n".trim(shell_exec("ss -lnt '( sport = :80 )'"))."\n";
foreach ($urls as $u) {
  echo basename(dirname(parse_url($u,PHP_URL_PATH))).'/'.basename($u).' '.trim(shell_exec('curl -sk --max-time 5 -o /dev/null -w "%{http_code} %{time_total}" -H "Host: sitefile.bahman.ir" '.escapeshellarg($u)))."\n";
}
echo "DONE\n";
